     3→import com.github.benmanes.caffeine.cache.Cache
     4→
     5→class DefaultLocalCache<ID : Any, V : Any>(
     6→    val cache: Cache<String, V>,
     7→    val keyPrefix: String,
     8→) : LocalCache<ID, V> {
     9→
    10→    override fun get(id: ID): V? =
    11→        cache.getIfPresent(id.toKey())
    12→
    13→    override fun getAll(ids: Collection<ID>): Map<ID, V?> {
    14→        val values: List<V?> = ids.map { id -> id.toKey() }
    15→            .map { key -> cache.getIfPresent(key) }
    16→
    17→        return ids.zip(values).associate {
    18→            it.first to it.second
    19→        }
    20→    }
    21→
    22→    override fun put(id: ID, value: V) {
    23→        cache.put(id.toKey(), value)
    24→    }
    25→
    26→    override fun putAll(values: Map<ID, V>) {
    27→        values
    28→            .map {it.key.toKey() to it.value }
    29→            .toMap()
    30→            .let { cache.putAll(it) }
    31→    }
    32→
    33→    private fun ID.toKey(): String = "$keyPrefix:id"
    34→}

